using System;
using System.IO;
using System.IO.Compression;
using System.Linq;
using System.Collections.Generic;
using System.Web.Script.Serialization;

namespace Zilda {
    public static class SelfTests {
        static int count;static List<string> lines=new List<string>();
        static void Test(string name,Action run){try{run();count++;lines.Add("PASS "+name);}catch(Exception ex){lines.Add("FAIL "+name+"\n"+ex);throw;}}
        static void Assert(bool b,string reason){if(!b)throw new Exception(reason);}
        static void Reject(Action run){bool rejected=false;try{run();}catch{rejected=true;}Assert(rejected,"Esperava rejeição.");}
        public static int Run(string root) {
            Directory.CreateDirectory(root);string fixtures=Path.Combine(root,"fixtures");Directory.CreateDirectory(fixtures);string desktop=Path.Combine(root,"desktop-simulado");Directory.CreateDirectory(desktop);
            Store s=null;Group g=null;string document=Path.Combine(fixtures,"relatório.txt"),link=Path.Combine(fixtures,"Pesquisa.url"),archive=Path.Combine(root,"backup.zip");
            try {
                Test("Primeiro uso cria três grupos e salva dados",delegate{s=new Store(Path.Combine(root,"dados"),desktop);g=s.Active.Groups[0];Assert(s.Active.Groups.Count==3,"grupos");Assert(File.Exists(Path.Combine(s.Root,"config.json")),"persistência");});
                Test("Documento é referenciado sem mover ou copiar original",delegate{File.WriteAllText(document,"conteúdo original");var e=s.Add(g,document,true);Assert(File.Exists(document)&&e.Copy==""&&e.Target==document,"documento alterado");});
                Test("Entrada duplicada não duplica atalho",delegate{Assert(s.Add(g,document,false)==null,"duplicado");Assert(g.Entries.Count==1,"contagem");});
                Test("Atalho URL é copiado e sobrevive à remoção da origem",delegate{File.WriteAllText(link,"[InternetShortcut]\r\nURL=https://example.org\r\n");var e=s.Add(g,link,false);File.Delete(link);Assert(File.Exists(s.Resolve(e)),"cópia inexistente");Assert(File.ReadAllText(s.Resolve(e)).Contains("https://example.org"),"conteúdo");});
                Test("Link web direto e validação de destino inexistente",delegate{var e=s.Add(g,"https://example.org/pasta?q=a",false);Assert(e.Target.StartsWith("https://"),"url");int before=g.Entries.Count;Reject(delegate{s.Add(g,Path.Combine(fixtures,"não existe.exe"),false);});Assert(g.Entries.Count==before,"mutação inválida");});
                Test("Modo cópia preserva .url da área de trabalho",delegate{string f=Path.Combine(desktop,"Copia.url");File.WriteAllText(f,"[InternetShortcut]\nURL=https://example.org");var e=s.Add(g,f,true);Assert(File.Exists(f)&&e.Archived=="","modo cópia");});
                Entry archived=null;string original=Path.Combine(desktop,"Arquivar.url");
                Test("Arquivamento opt-in preserva original e cópia",delegate{s.Active.Options.ArchiveDesktop=true;File.WriteAllText(original,"[InternetShortcut]\nURL=https://example.org/arquivo");archived=s.Add(g,original,true);Assert(!File.Exists(original)&&File.Exists(s.Local(archived.Archived))&&File.Exists(s.Resolve(archived)),"arquivamento");});
                Test("Clonar perfil não duplica propriedade do arquivo original",delegate{var p=s.Clone(s.Active,"Cópia");Assert(p.Groups.SelectMany(x=>x.Entries).All(e=>e.Archived==""),"arquivo duplicado");Assert(p.Groups[0].Id!=g.Id,"id duplicado");});
                Test("Remover restaura sem sobrescrever arquivo já existente",delegate{File.WriteAllText(original,"NÃO SOBRESCREVER");s.Remove(g,archived);Assert(File.ReadAllText(original)=="NÃO SOBRESCREVER","sobrescreveu");Assert(File.Exists(Path.Combine(desktop,"Arquivar (2).url")),"restauração faltante");});
                Test("Reabrir recupera perfil, preferências e ordem",delegate{g.Layout="Anel";s.Active.Options.Theme="Claro";s.Save();var reopened=new Store(s.Root,desktop);Assert(reopened.Active.Groups[0].Layout=="Anel"&&reopened.Active.Options.Theme=="Claro","serialização");Assert(reopened.Active.Groups[0].Entries[0].Target==document,"ordem");});
                Test("Backup válido restaura para outra pasta de dados",delegate{s.Backup(archive);var other=new Store(Path.Combine(root,"restaurado"),desktop);other.Import(archive);Assert(other.Active.Groups[0].Layout=="Anel","layout");Assert(other.Data.Profiles.Count==s.Data.Profiles.Count,"perfis");Assert(other.Active.Groups[0].Entries.Where(e=>e.Copy!="").All(e=>File.Exists(other.Resolve(e))),"cópias");Assert(Directory.GetFiles(other.Root,"antes-da-importacao-*.zip").Length==1,"backup preventivo");});
                Test("ZIP com travessia de pasta é rejeitado sem alterar dados",delegate{string bad=Path.Combine(root,"malicioso.zip");using(var z=ZipFile.Open(bad,ZipArchiveMode.Create)){var e=z.CreateEntry("../escape.txt");using(var w=new StreamWriter(e.Open()))w.Write("no");}string before=File.ReadAllText(Path.Combine(s.Root,"config.json"));Reject(delegate{s.Import(bad);});Assert(before==File.ReadAllText(Path.Combine(s.Root,"config.json")),"config alterada");Assert(!File.Exists(Path.Combine(root,"escape.txt")),"escape");});
                Test("ZIP com entrada duplicada é rejeitado",delegate{string bad=Path.Combine(root,"duplicado.zip");using(var z=ZipFile.Open(bad,ZipArchiveMode.Create)){z.CreateEntry("config.json");z.CreateEntry("config.json");}Reject(delegate{s.Import(bad);});});
                Test("Backup com caminho absoluto de cópia é rejeitado",delegate{var serial=new JavaScriptSerializer();var bad=serial.Deserialize<State>(serial.Serialize(s.Data));bad.Profiles[0].Groups[0].Entries[0].Copy=@"C:\Windows\escape.lnk";Reject(delegate{Store.Validate(bad);});});
                Test("Preferências e coordenadas fora dos limites são rejeitadas",delegate{var serial=new JavaScriptSerializer();var bad=serial.Deserialize<State>(serial.Serialize(s.Data));bad.Profiles[0].Options.Columns=0;Reject(delegate{Store.Validate(bad);});bad.Profiles[0].Options.Columns=4;bad.Profiles[0].Groups[0].X=Double.NaN;Reject(delegate{Store.Validate(bad);});});
                Test("ID vazio e destino excessivo são rejeitados antes da mutação",delegate{var serial=new JavaScriptSerializer();var bad=serial.Deserialize<State>(serial.Serialize(s.Data));bad.Profiles[0].Groups[0].Id="";Reject(delegate{Store.Validate(bad);});int before=g.Entries.Count;Reject(delegate{s.Add(g,"https://example.org/"+new String('a',8200),false);});Assert(g.Entries.Count==before,"entrada inválida permaneceu");s.Save();});
                Test("Ícones internos sobrevivem ao backup e à mudança da pasta de dados",delegate{string icon="atalhos\\icone-teste.ico";File.WriteAllBytes(s.Local(icon),new byte[]{0,1,2,3});g.Icon=icon;s.Save();string b=Path.Combine(root,"icone-backup.zip");s.Backup(b);var other=new Store(Path.Combine(root,"icone-restaurado"),desktop);other.Import(b);string local=other.Active.Groups[0].Icon;Assert(!Path.IsPathRooted(local)&&File.Exists(other.Local(local)),"ícone não remapeado");Assert(File.ReadAllBytes(other.Local(local)).Length==4,"ícone incompleto");});
                Test("Restauração total recupera originais órfãos de configuração perdida",delegate{string orphan=Path.Combine(s.Root,"arquivo","orfao.url");File.WriteAllText(orphan,"[InternetShortcut]\nURL=https://example.org/orfao");s.RestoreAll();Assert(!File.Exists(orphan),"órfão não restaurado");Assert(File.Exists(Path.Combine(desktop,"Atalho recuperado - orfao.url")),"órfão perdido");});
                Test("Backup restaura arquivos originais sob responsabilidade do novo estado",delegate{string file=Path.Combine(desktop,"Backup-original.url");File.WriteAllText(file,"[InternetShortcut]\nURL=https://example.org/backup");var e=s.Add(g,file,true);string backup=Path.Combine(root,"originais-backup.zip");s.Backup(backup);var other=new Store(Path.Combine(root,"originais-importados"),desktop);other.Import(backup);var imported=other.Active.Groups[0].Entries.First(x=>x.Id==e.Id);Assert(File.Exists(other.Local(imported.Archived)),"arquivo importado foi restaurado antes da hora");Assert(!File.Exists(file),"original não deveria ter sido devolvido");});
                Test("Usar link web como ícone mantém configuração válida",delegate{var entry=g.Entries.First(e=>e.Target.StartsWith("https://"));s.UseIcon(g,entry);Assert(g.Icon==""&&g.Symbol=="↗","símbolo de link");Store.Validate(s.Data);});
                Test("Configuração corrompida usa backup e preserva arquivo danificado",delegate{string target=Path.Combine(s.Root,"config.json");File.WriteAllText(target,"CORROMPIDO");var recovered=new Store(s.Root,desktop);Assert(recovered.Warning!="","aviso");Assert(recovered.Data.Profiles.Count>0,"recuperação");Assert(Directory.GetFiles(s.Root,"config-danificado-*.json").Length==1,"cópia danificada");});
                Test("Configuração corrompida sem backup cria estado válido",delegate{string d=Path.Combine(root,"danificado-sem-backup");Directory.CreateDirectory(d);File.WriteAllText(Path.Combine(d,"config.json"),"{\"Version\":99}");var recovered=new Store(d,desktop);Store.Validate(recovered.Data);Assert(recovered.Warning!="","aviso");});
                Test("Cinco layouts possuem posições distintas e dimensões válidas",delegate{foreach(string layout in Store.Layouts)foreach(int n in new[]{0,1,5,10,16}){var p=Plan.Make(layout,n,new Preferences());Assert(p.Width>0&&p.Height>0&&p.Points.Count==n,"dimensão "+layout);Assert(p.Points.Select(x=>x.ToString()).Distinct().Count()==n,"sobreposição "+layout);foreach(var pt in p.Points)Assert(pt.X>=0&&pt.Y>=0&&pt.X+74<=p.Width+1&&pt.Y+74<=p.Height+1,"limite "+layout+" "+n);}});
                lines.Add("TOTAL "+count+" testes aprovados");File.WriteAllLines(Path.Combine(root,"resultados.txt"),lines);return 0;
            }catch{File.WriteAllLines(Path.Combine(root,"resultados.txt"),lines);return 1;}
        }
    }
}
